<div class="content"><header class="topbar"><div><div class="topbar__eyebrow">Biens immobiliers</div><div class="topbar__title">Créer une nouvelle fiche</div></div><a class="button button--ghost" href="index.php">Retour à la liste</a></header><main class="page"><div class="page__header"><div><h1 class="page__title"><?= htmlspecialchars($title ?? 'Bien', ENT_QUOTES, 'UTF-8') ?></h1><p class="page__subtitle">Renseignez les informations essentielles de votre bien.</p></div></div><section class="card"><div class="card__body"><?php if (isset($errors['general'])): ?><div class="alert alert--error"><?= htmlspecialchars($errors['general'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php foreach ($errors as $field => $error): if ($field !== 'general'): ?><div class="alert alert--error"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; endforeach; ?><form method="post" action="<?= htmlspecialchars($action, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><div class="form-grid"><label>Référence<input name="reference" maxlength="100" placeholder="Ex. LOKA-APT-001" required value="<?= htmlspecialchars((string) ($property['reference'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></label><label>Titre<input name="titre" maxlength="200" placeholder="Ex. Appartement lumineux centre-ville" required value="<?= htmlspecialchars((string) ($property['titre'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></label><label>Type<select name="id_type_bien" required><?php foreach ($references['types'] as $type): ?><option value="<?= (int) $type['id_type_bien'] ?>"<?= (string) ($property['id_type_bien'] ?? '') === (string) $type['id_type_bien'] ? ' selected' : '' ?>><?= htmlspecialchars($type['nom'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Adresse<select name="id_adresse" required><?php foreach ($references['adresses'] as $address): ?><option value="<?= (int) $address['id_adresse'] ?>"