d' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="full">Description<textarea name="description" placeholder="Décrivez les caractéristiques du bien..."><?= htmlspecialchars((string) ($property['description'] ?? ''), ENT_QUOTES, 'UTF-8') ?></textarea></label></div><div class="form-actions"><a class="button button--ghost" href="index.php">Annuler</a><button class="button--primary" type="submit">Enregistrer le bien</button></div></form></div></section></main></div></div></body></html>
